-- One starter example for 16 non-Physics THPT subjects, not exact textbook lessons.
insert into public.edubridge_ready_lessons(slug,subject,grade,sort_order,chapter,title,source_text)
select slug,subject,grade,sort_order,chapter,title,source_text from jsonb_to_recordset($seed$[{"slug":"thpt-intro-01","subject":"Ngữ văn","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Đọc hiểu văn bản và tìm bằng chứng","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Ngữ văn. Bài minh họa lớp 10: Đọc hiểu văn bản và tìm bằng chứng.\nKiến thức trọng tâm: Đọc một văn bản cần xác định ngữ cảnh, chủ đề, người kể chuyện hoặc chủ thể trữ tình và chi tiết then chốt. Ý kiến phân tích phải gắn với bằng chứng trong văn bản. Cần phân biệt điều tác giả viết trực tiếp với suy luận của người đọc và lí giải vì sao cách hiểu hợp lí.\nHoạt động học tập: Đọc một đoạn văn được phép sử dụng và chọn một dẫn chứng cho ý chính.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-02","subject":"Toán","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Hàm số và đồ thị","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Toán. Bài minh họa lớp 10: Hàm số và đồ thị.\nKiến thức trọng tâm: Hàm số gán cho mỗi giá trị x trong tập xác định một giá trị y. Đồ thị biểu diễn quan hệ giữa hai đại lượng trên hệ trục tọa độ. Với hàm bậc hai y=ax²+bx+c (a khác 0), đồ thị là parabol; phải xem tập xác định và chiều biến thiên trong miền xét. Giải thích ý nghĩa dữ liệu trước khi kết luận.\nHoạt động học tập: Vẽ đồ thị y=(x−1)² và tìm đỉnh cùng giao điểm trục tung.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-03","subject":"Ngoại ngữ 1","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Giao tiếp và tự giới thiệu","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Ngoại ngữ 1. Bài minh họa lớp 10: Giao tiếp và tự giới thiệu.\nKiến thức trọng tâm: Một đoạn tự giới thiệu có thể nêu tên, sở thích, hoạt động học tập và mục tiêu. Lựa chọn từ vựng và cấu trúc phù hợp bối cảnh, người nghe và mục đích. Giao tiếp hiệu quả còn cần chú ý phát âm rõ ràng, lượt nói, câu hỏi tiếp nối và thái độ lịch sự. Tránh dịch từng từ máy móc từ tiếng mẹ đẻ.\nHoạt động học tập: Chuẩn bị sáu câu giới thiệu bằng tiếng Anh và hai câu hỏi giao tiếp.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-04","subject":"Lịch sử","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Tư liệu và đánh giá nguồn sử liệu","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Lịch sử. Bài minh họa lớp 10: Tư liệu và đánh giá nguồn sử liệu.\nKiến thức trọng tâm: Cần phân biệt nguồn sơ cấp và thứ cấp trong nghiên cứu lịch sử. Khi đọc một nguồn, xem xét người tạo ra tư liệu, thời gian, bối cảnh và mục đích. So sánh nhiều tư liệu có thể giúp nhận ra sự khác biệt trong cách ghi nhận cùng sự kiện. Không xem một ý kiến chủ quan trong tư liệu là kết luận lịch sử đã kiểm chứng.\nHoạt động học tập: So sánh hai tường thuật về một sự kiện, xác định thông tin giống và khác.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-05","subject":"Giáo dục thể chất","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Khởi động và luyện tập an toàn","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Giáo dục thể chất. Bài minh họa lớp 10: Khởi động và luyện tập an toàn.\nKiến thức trọng tâm: Khởi động giúp hệ cơ – khớp và tuần hoàn thích nghi dần với vận động. Cường độ tập luyện nên phù hợp thể trạng và được tăng dần theo mục tiêu. Cần chú ý uống nước, thời gian nghỉ và dấu hiệu bất thường. Khi bị đau hoặc chóng mặt phải dừng hoạt động và báo giáo viên. Không lấy cảm giác mệt làm chỉ số duy nhất về hiệu quả.\nHoạt động học tập: Thiết kế chuỗi khởi động ngắn trước bài tập chạy và giải thích mục đích.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-06","subject":"Giáo dục quốc phòng và an ninh","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Kỷ luật và trách nhiệm tập thể","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Giáo dục quốc phòng và an ninh. Bài minh họa lớp 10: Kỷ luật và trách nhiệm tập thể.\nKiến thức trọng tâm: Giáo dục quốc phòng và an ninh góp phần xây dựng tinh thần trách nhiệm công dân, tác phong kỷ luật, đoàn kết và ý thức chấp hành quy định. Trong mọi hoạt động thực hành, học sinh phải tuân thủ chỉ dẫn của giáo viên và nội quy an toàn. Thảo luận tình huống nên dựa vào mục tiêu bảo vệ bản thân và cộng đồng.\nHoạt động học tập: Tổ chức thảo luận nhóm về ba nguyên tắc an toàn khi thực hành.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-07","subject":"Địa lí","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Đọc bản đồ và số liệu địa lí","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Địa lí. Bài minh họa lớp 10: Đọc bản đồ và số liệu địa lí.\nKiến thức trọng tâm: Đọc bản đồ cần hiểu chú giải, tỉ lệ, phương hướng, phạm vi lãnh thổ và thời điểm số liệu. Nhận xét phân bố không gian cần dựa vào chứng cứ từ bản đồ và các nguồn liên quan. Một số hiện tượng địa lí do nhiều nhân tố tác động nên không thể khẳng định nguyên nhân chỉ từ một hình ảnh. Khi so sánh vùng cần sử dụng cùng đơn vị và tiêu chí.\nHoạt động học tập: Mô tả sự phân bố một hiện tượng trên bản đồ chuyên đề và nêu hai câu hỏi điều tra thêm.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-08","subject":"Giáo dục kinh tế và pháp luật","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Lập ngân sách cá nhân","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Giáo dục kinh tế và pháp luật. Bài minh họa lớp 10: Lập ngân sách cá nhân.\nKiến thức trọng tâm: Vì nguồn lực có giới hạn nên cá nhân cần phân biệt nhu cầu thiết yếu với mong muốn, cân đối thu và chi, dự phòng rủi ro. Chi phí cơ hội của lựa chọn là lợi ích của phương án tốt nhất bị bỏ qua. Khi ra quyết định tiêu dùng, cần kiểm tra thông tin, điều kiện giao dịch và quy định bảo vệ quyền lợi người tiêu dùng.\nHoạt động học tập: Thiết kế bảng thu chi một tuần, phân loại thiết yếu và không thiết yếu.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-09","subject":"Hóa học","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Cấu tạo nguyên tử và nguyên tố","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Hóa học. Bài minh họa lớp 10: Cấu tạo nguyên tử và nguyên tố.\nKiến thức trọng tâm: Một nguyên tử có hạt nhân chứa proton và neutron, cùng các electron chuyển động trong vùng không gian quanh hạt nhân. Số proton bằng số hiệu nguyên tử Z; nguyên tử trung hòa có số electron bằng Z. Những nguyên tử cùng Z nhưng khác số neutron là các đồng vị. Khi biểu diễn ion cần nêu điện tích và số electron tương ứng.\nHoạt động học tập: Phân biệt nguyên tử trung hòa và ion có cùng số proton.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-10","subject":"Sinh học","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Tế bào và các thành phần","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Sinh học. Bài minh họa lớp 10: Tế bào và các thành phần.\nKiến thức trọng tâm: Tế bào là đơn vị cấu trúc và chức năng cơ bản của cơ thể sống. Màng sinh chất đóng vai trò điều tiết trao đổi chất; tế bào chất chứa nhiều cấu trúc hỗ trợ hoạt động sống; vật chất di truyền mang thông tin sinh học. Không phải mọi loại tế bào đều có nhân thực hay đầy đủ cùng một loại bào quan. Cần quan sát bằng chứng khi mô tả tế bào.\nHoạt động học tập: Vẽ sơ đồ tế bào minh họa và gắn nhãn ba thành phần cơ bản.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-11","subject":"Công nghệ","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Từ nhu cầu tới nguyên mẫu","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Công nghệ. Bài minh họa lớp 10: Từ nhu cầu tới nguyên mẫu.\nKiến thức trọng tâm: Thiết kế công nghệ khởi đầu từ xác định nhu cầu, yêu cầu sử dụng và ràng buộc thực tế. Sau khi đề xuất giải pháp, có thể tạo nguyên mẫu, đánh giá bằng tiêu chí rõ ràng và cải tiến dựa trên kết quả kiểm thử. Cần đồng thời xem xét chức năng, an toàn, chi phí, khả năng sửa chữa và ảnh hưởng môi trường.\nHoạt động học tập: Đề xuất bản thiết kế và hai phép thử cho giá đỡ điện thoại tái chế.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-12","subject":"Tin học","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Thuật toán và kiểm thử","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Tin học. Bài minh họa lớp 10: Thuật toán và kiểm thử.\nKiến thức trọng tâm: Thuật toán gồm các bước hữu hạn và rõ ràng để xử lý dữ liệu đầu vào nhằm tạo đầu ra mong muốn. Khi viết thuật toán, cần nêu điều kiện, trường hợp đặc biệt và cách kiểm chứng kết quả. Không chỉ thử một ví dụ thuận lợi; cần kiểm tra dữ liệu ở biên. Chú ý quyền riêng tư và bảo vệ thông tin người dùng khi thiết kế phần mềm.\nHoạt động học tập: Viết các bước tìm số lớn nhất trong ba số và lập danh sách kiểm thử.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-13","subject":"Âm nhạc","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Nhịp điệu và tiết tấu","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Âm nhạc. Bài minh họa lớp 10: Nhịp điệu và tiết tấu.\nKiến thức trọng tâm: Nhịp điệu liên quan cách phân bố trường độ của âm thanh trong thời gian. Phách mạnh – nhẹ, tốc độ và cách phối hợp nhóm góp phần tạo biểu cảm. Cần phân biệt tiết tấu với giai điệu và lắng nghe sắc thái khi trình bày. Học sinh có thể dùng kí hiệu nhạc hoặc nhạc cụ gõ đơn giản để diễn đạt ý tưởng.\nHoạt động học tập: Sáng tác mẫu gõ bốn ô nhịp rồi thực hiện với hai tốc độ khác nhau.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-14","subject":"Mĩ thuật","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Bố cục và điểm nhấn","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Mĩ thuật. Bài minh họa lớp 10: Bố cục và điểm nhấn.\nKiến thức trọng tâm: Trong tạo hình, đường nét, hình khối, màu sắc, đậm nhạt và không gian được sắp xếp để truyền tải ý tưởng. Bố cục có thể tạo cảm giác cân bằng hoặc chuyển động qua nhịp điệu thị giác và độ tương phản. Một chủ đề có thể có nhiều cách thể hiện; khi nhận xét tác phẩm cần nói rõ yếu tố quan sát được trước khi nêu cảm nhận.\nHoạt động học tập: Phác thảo hai bố cục áp phích bảo vệ môi trường và so sánh điểm nhấn.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-15","subject":"Ngoại ngữ 2","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Phương pháp học từ mới","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Ngoại ngữ 2. Bài minh họa lớp 10: Phương pháp học từ mới.\nKiến thức trọng tâm: Để học ngoại ngữ thứ hai, người học kết nối âm thanh, chữ viết, ý nghĩa và tình huống giao tiếp. Ôn cách quãng và sử dụng từ trong câu phù hợp ngữ cảnh giúp củng cố trí nhớ. Cấu trúc ngữ pháp và quy tắc phát âm phải dựa vào ngôn ngữ thực tế được lựa chọn, không áp dụng máy móc mô hình tiếng Anh cho mọi thứ tiếng.\nHoạt động học tập: Lập bộ thẻ từ của ngoại ngữ đang học và dùng ba từ để tạo câu.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."},{"slug":"thpt-intro-16","subject":"Tiếng dân tộc thiểu số","grade":"10","sort_order":1,"chapter":"EDUBRIDGE – Học liệu minh họa","title":"Bài khởi đầu. Giao tiếp tôn trọng ngôn ngữ bản địa","source_text":"TÀI LIỆU EDUBRIDGE TỰ BIÊN SOẠN – KHÔNG PHẢI NỘI DUNG NGUYÊN VĂN SGK.\nMôn học: Tiếng dân tộc thiểu số. Bài minh họa lớp 10: Giao tiếp tôn trọng ngôn ngữ bản địa.\nKiến thức trọng tâm: Học một ngôn ngữ bản địa cần bám tài liệu được xác nhận bởi cộng đồng và người dạy có chuyên môn, đồng thời tôn trọng khác biệt phương ngữ, cách xưng hô và bối cảnh văn hóa. Không thể tự suy ra cách dùng từ hoặc quy tắc của một tiếng dân tộc cụ thể khi chưa xác định ngôn ngữ. Hoạt động học tập ưu tiên lắng nghe, ghi chép và thực hành có hướng dẫn.\nHoạt động học tập: Xây dựng bảng tình huống chào hỏi rồi tham vấn giáo viên về cách diễn đạt đúng.\nGhi chú: Cần đối chiếu chương trình và tài liệu môn cụ thể trước khi sử dụng chính thức."}]$seed$::jsonb) as r(slug text,subject text,grade text,sort_order integer,chapter text,title text,source_text text)
on conflict(slug) do update set title=excluded.title,source_text=excluded.source_text,updated_at=now();